function gsnappy {
    $sdioDir = "$env:TEMP\SDIO"
    $zipPath = "$env:TEMP\sdio.zip"
    $baseUrl = "https://www.glenn.delahoy.com/downloads/sdio/"
    Write-Host "[gsnappy] Resolving latest SDIO version..." -ForegroundColor Cyan
    $zipUrl = "${baseUrl}SDIO_1.17.8.829.zip"
    try {
        $page = (Invoke-WebRequest -Uri "https://www.glenn.delahoy.com/snappy-driver-installer-origin/" -UseBasicParsing).Content
        $m = [regex]::Match($page, 'SDIO_([\d.]+)\.zip')
        if ($m.Success) { $zipUrl = "${baseUrl}SDIO_$($m.Groups[1].Value).zip"; Write-Host "[gsnappy] Latest: $($m.Groups[1].Value)" -ForegroundColor Green }
    } catch { Write-Host "[gsnappy] Using known latest." -ForegroundColor Yellow }
    Write-Host "[gsnappy] Downloading..." -ForegroundColor Cyan
    try { Invoke-WebRequest -Uri $zipUrl -OutFile $zipPath -UseBasicParsing } catch { Write-Host "[gsnappy] Download failed: $_" -ForegroundColor Red; return }
    if (-not (Test-Path $zipPath) -or (Get-Item $zipPath).Length -lt 500KB) { Write-Host "[gsnappy] Download failed or too small." -ForegroundColor Red; return }
    Write-Host "[gsnappy] Downloaded: $([math]::Round((Get-Item $zipPath).Length/1MB,1)) MB" -ForegroundColor Gray
    if (Test-Path $sdioDir) { Remove-Item $sdioDir -Recurse -Force }
    Expand-Archive -Path $zipPath -DestinationPath $sdioDir -Force
    Remove-Item $zipPath -Force
    $sdio = Get-ChildItem -Path $sdioDir -Recurse -Filter "SDIO_x64_R*.exe" | Select-Object -First 1
    if (-not $sdio) { $sdio = Get-ChildItem -Path $sdioDir -Recurse -Filter "SDIO*.exe" | Where-Object { $_.Name -notmatch 'x86' } | Select-Object -First 1 }
    if (-not $sdio) { Write-Host "[gsnappy] SDIO exe not found." -ForegroundColor Red; return }
    Write-Host "[gsnappy] Launching: auto-download indexes, scan, install needed drivers." -ForegroundColor Green
    Start-Process -FilePath $sdio.FullName -ArgumentList "-license -expertmode -checkupdates -autoupdate -autoinstall -onlyupdates -preservecfg" -WorkingDirectory $sdio.DirectoryName -Verb RunAs -WindowStyle Normal
}

